package com.fincore.fincore.security;
import java.io.IOException; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final CustomUserDetailsService users; public JwtAuthenticationFilter(JwtService j,CustomUserDetailsService u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader(HttpHeaders.AUTHORIZATION); if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){var u=users.loadUserByUsername(jwt.username(t));var a=new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());SecurityContextHolder.getContext().setAuthentication(a);}} chain.doFilter(req,res);} }
